def pacificAtlantic(heights: List[List[int]]) -> List[List[int]]:
    m, n = len(heights), len(heights[0])
    pac, atl = set(), set()

    def climb(r: int, c: int, seen: set) -> None:
        if (r, c) in seen: return
        seen.add((r, c))
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and heights[nr][nc] >= heights[r][c]: climb(nr, nc, seen)

    for r in range(m):
        climb(r, 0, pac)
        climb(r, n - 1, atl)
    for c in range(n):
        climb(0, c, pac)
        climb(m - 1, c, atl)
    return [[r, c] for r in range(m) for c in range(n) if (r, c) in pac and (r, c) in atl]

